-- Тема 01: варианты ответов выровнены по длине и форме (40 исправлений в 14 вопросах), ключи не меняются.
-- Источник: scripts/questions/087_option_length_topic01.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Что такое кластер баз данных в PostgreSQL?', 'Группа серверов, объединённых для отказоустойчивости', 'Группа серверов для отказоустойчивости', 'Так обычно называют группу серверов для высокой доступности, а в PostgreSQL кластер баз данных означает другое.', NULL),
        ('option', 'Что такое кластер баз данных в PostgreSQL?', 'Набор баз данных, которыми управляет один экземпляр сервера', 'Набор баз данных одного экземпляра сервера', 'Все базы кластера обслуживает один экземпляр сервера; данные лежат в PGDATA и в каталогах табличных пространств.', NULL),
        ('option', 'Что такое кластер баз данных в PostgreSQL?', 'Таблица, разбитая на секции', 'Таблица, разбитая на несколько секций', 'Это секционированная таблица.', NULL),
        ('option', 'Что такое кластер баз данных в PostgreSQL?', 'Основной сервер вместе с репликами', 'Основной сервер вместе с его репликами', 'Это схема репликации, а не кластер баз данных.', NULL),
        ('option', 'Какой ключ initdb включает контрольные суммы страниц данных?', '-k (--data-checksums)', '-k, --data-checksums', 'Включает подсчёт контрольных сумм при создании кластера.', NULL),
        ('option', 'Какой ключ initdb включает контрольные суммы страниц данных?', '-c', '-c, --set имя=значение', 'Задаёт значение параметра конфигурации (ключ появился в PostgreSQL 16).', NULL),
        ('option', 'Какой ключ initdb включает контрольные суммы страниц данных?', '-D', '-D, --pgdata каталог', 'Задаёт каталог кластера.', NULL),
        ('option', 'Какой ключ initdb включает контрольные суммы страниц данных?', '-U', '-U, --username имя', 'Задаёт имя суперпользователя СУБД.', NULL),
        ('option', 'Чем make world отличается от make при сборке из исходных кодов?', 'Дополнительно собирает расширения и документацию', 'Собирает также расширения и всю документацию', 'Кроме сервера собираются дополнительные модули и документация.', 'Кроме сервера собираются дополнительные модули (contrib) и документация.'),
        ('option', 'Чем make world отличается от make при сборке из исходных кодов?', 'Сразу устанавливает собранное', 'Сразу устанавливает собранное в систему', 'Установку выполняет отдельная команда make install или make install-world.', NULL),
        ('option', 'Чем make world отличается от make при сборке из исходных кодов?', 'Скачивает свежую версию из git', 'Скачивает свежую версию из репозитория git', 'make работает с уже полученными исходными кодами и ничего не скачивает.', NULL),
        ('option', 'Включены ли контрольные суммы страниц в кластере, созданном пакетом Ubuntu?', 'Нет, по умолчанию выключены', 'Нет, они выключены по умолчанию', 'По умолчанию пакет создаёт кластер без контрольных сумм.', NULL),
        ('option', 'Включены ли контрольные суммы страниц в кластере, созданном пакетом Ubuntu?', 'Да, всегда', 'Да, включены при создании кластера', 'Они включаются только явно.', 'Они включаются явно: при создании кластера ключом -k или позже утилитой pg_checksums.'),
        ('option', 'Включены ли контрольные суммы страниц в кластере, созданном пакетом Ubuntu?', 'Пакет их не поддерживает', 'Пакет Ubuntu их не поддерживает', 'Поддерживаются: их можно включить утилитой pg_checksums.', NULL),
        ('option', 'Как включить контрольные суммы в уже существующем кластере?', 'pg_ctl reload', 'Выполнить pg_ctl reload без остановки', 'Только перечитывает конфигурацию, контрольные суммы так не включаются.', NULL),
        ('option', 'Какие утилиты добавлены пакетами Debian и Ubuntu и не входят в стандартную поставку PostgreSQL?', '`pg_ctlcluster`', 'Утилита `pg_ctlcluster` для кластера', 'Да. Это обёртка Ubuntu и Debian над pg_ctl: запускает, останавливает и перезапускает кластер по номеру версии и имени. В стандартном PostgreSQL её нет, её добавил пакет postgresql-common.', NULL),
        ('option', 'Какие утилиты добавлены пакетами Debian и Ubuntu и не входят в стандартную поставку PostgreSQL?', '`pg_createcluster`', 'Утилита `pg_createcluster` для кластера', 'Да. Это обёртка Ubuntu и Debian над initdb: создаёт новый кластер и сразу кладёт настройки в /etc/postgresql. В стандартном PostgreSQL её нет, её добавил пакет postgresql-common.', NULL),
        ('option', 'Какие утилиты добавлены пакетами Debian и Ubuntu и не входят в стандартную поставку PostgreSQL?', '`pg_ctl`', 'Утилита `pg_ctl` для управления сервером', 'Нет. pg_ctl входит в стандартную поставку PostgreSQL (пакет postgresql-16), Ubuntu и Debian её не добавляли. Поверх неё они сделали pg_ctlcluster.', NULL),
        ('option', 'Какие утилиты добавлены пакетами Debian и Ubuntu и не входят в стандартную поставку PostgreSQL?', '`initdb`', 'Утилита `initdb` для создания кластера', 'Нет. initdb входит в стандартную поставку PostgreSQL (пакет postgresql-16), Ubuntu и Debian её не добавляли. Поверх неё они сделали pg_createcluster.', NULL),
        ('option', 'Что верно для утилиты initdb?', 'Может работать от имени root', 'Может работать от имени пользователя root', 'От имени root initdb работать откажется.', NULL),
        ('option', 'Что верно для утилиты initdb?', 'Запускает сервер после инициализации', 'Запускает сервер после инициализации кластера', 'Сервер запускают отдельно, например pg_ctl start.', NULL),
        ('option', 'Что верно для утилиты initdb?', 'Создаёт файлы конфигурации в каталоге кластера', 'Создаёт файлы конфигурации в кластере', 'В каталоге кластера появляются postgresql.conf, pg_hba.conf и pg_ident.conf.', NULL),
        ('option', 'Сервер собран командами make и make install. Как собрать и установить расширения из contrib?', 'Выполнить make и make install в подкаталоге contrib', 'Выполнить make и make install в contrib', 'Так и делается: расширения собираются отдельно от сервера.', 'Так и делается: расширения собираются отдельно от сервера, в подкаталоге contrib.'),
        ('option', 'Для чего нужна библиотека readline?', 'Для редактирования командной строки, истории и автодополнения в psql', 'Для редактирования команд и истории в psql', 'В серверной установке может быть не нужна, если psql в консоли не запускают.', 'Даёт редактирование командной строки, историю и автодополнение в psql; в серверной установке может быть не нужна, если psql в консоли не запускают.'),
        ('option', 'Для чего нужна библиотека readline?', 'Для шифрования соединений', 'Для шифрования соединений с сервером', 'Шифрование обеспечивает OpenSSL.', NULL),
        ('option', 'Для чего нужна библиотека readline?', 'Для сжатия данных', 'Для сжатия данных в таблицах и WAL', 'Для сжатия служат zlib, lz4 и zstd.', NULL),
        ('option', 'Где в пакете Ubuntu находится каталог данных кластера main версии 16?', '`/etc/postgresql/16/main`', '`/etc/postgresql/16/main/conf.d`', 'Здесь лежат файлы конфигурации кластера.', NULL),
        ('option', 'Где в пакете Ubuntu находится каталог данных кластера main версии 16?', '`/usr/lib/postgresql/16`', '`/usr/lib/postgresql/16/bin`', 'Здесь лежат программы сервера, их владелец — root.', NULL),
        ('option', 'Скрипт ./configure при сборке из исходных кодов завершился ошибкой. Где подробно записано, какая проверка не прошла и почему?', 'В журнале сообщений сервера', 'В журнале сообщений сервера после сборки', 'Сервера ещё нет: configure только готовит сборку.', NULL),
        ('option', 'Скрипт ./configure при сборке из исходных кодов завершился ошибкой. Где подробно записано, какая проверка не прошла и почему?', 'В файле `config.log` в каталоге, где запускали configure', 'В файле `config.log` рядом с configure', 'Туда configure пишет свои проверки и вывод компилятора.', 'Туда configure пишет свои проверки и вывод компилятора; файл лежит в каталоге, где запускали configure.'),
        ('option', 'Скрипт ./configure при сборке из исходных кодов завершился ошибкой. Где подробно записано, какая проверка не прошла и почему?', 'В файле `Makefile`', 'В файле `Makefile` после запуска configure', 'Это инструкции для make, отчёта о проверках в нём нет.', NULL),
        ('option', 'Скрипт ./configure при сборке из исходных кодов завершился ошибкой. Где подробно записано, какая проверка не прошла и почему?', 'В каталоге `/var/log/postgresql`', 'В каталоге `/var/log/postgresql` пакета', 'Это журналы пакетной установки Ubuntu, к сборке они не относятся.', NULL),
        ('option', 'Что при сборке PostgreSQL 16 из исходных кодов включается только явным ключом configure вида --with-…?', 'Библиотека readline для psql', 'Библиотека readline для работы psql', 'Используется по умолчанию, отключается ключом --without-readline.', NULL),
        ('option', 'Что при сборке PostgreSQL 16 из исходных кодов включается только явным ключом configure вида --with-…?', 'Поддержка ICU', 'Поддержка ICU для правил сортировки', 'С версии 16 используется по умолчанию, отключается ключом --without-icu.', NULL),
        ('option', 'Как узнать, включены ли контрольные суммы страниц в кластере?', 'Выполнить `pg_ctl status`', 'Выполнить `pg_ctl status` и изучить параметры запуска', 'Показывает только, запущен ли сервер, его PID и параметры запуска.', NULL),
        ('option', 'Как узнать, включены ли контрольные суммы страниц в кластере?', 'Посмотреть строку «Data page checksum version» в выводе `pg_controldata`', 'Строка «Data page checksum version» в `pg_controldata`', '0 — выключены, иное значение — включены.', NULL),
        ('option', 'В репозитории вашей версии Ubuntu есть PostgreSQL 14, а нужен 16. Как установить его по рекомендации postgresql.org?', 'Выполнить `apt upgrade`', 'Выполнить `apt upgrade` и перезагрузить сервер', 'Обновит только ту версию, что есть в репозитории Ubuntu, новой основной версии не даст.', NULL),
        ('option', 'В репозитории вашей версии Ubuntu есть PostgreSQL 14, а нужен 16. Как установить его по рекомендации postgresql.org?', 'Собрать PostgreSQL 16 из исходных кодов', 'Собрать PostgreSQL 16 из исходных кодов вручную', 'Можно, но тогда установка и обновления на вас; в обычном случае сборка не нужна.', NULL),
        ('option', 'В репозитории вашей версии Ubuntu есть PostgreSQL 14, а нужен 16. Как установить его по рекомендации postgresql.org?', 'Скачать пакет postgresql-16 от другой версии Ubuntu', 'Скачать пакет postgresql-16 от другой версии Ubuntu вручную', 'Пакеты собраны под свой выпуск, зависимости могут не совпасть.', NULL),
        ('option', 'В репозитории вашей версии Ubuntu есть PostgreSQL 14, а нужен 16. Как установить его по рекомендации postgresql.org?', 'Подключить репозиторий `apt.postgresql.org` и установить пакет `postgresql-16`', 'Подключить `apt.postgresql.org`, поставить `postgresql-16`', 'Репозиторий даёт все поддерживаемые версии и обновления через обычный apt.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
